import SwiftUI
import SyncSpaceKit

struct IOSTransfersView: View { @EnvironmentObject private var state: SyncSpaceAppState; var body: some View { List { Section("Active") { if state.transferManager.active.isEmpty { ContentUnavailableView("No active transfers", systemImage: "arrow.left.arrow.right") }; ForEach(state.transferManager.active) { transfer in TransferRow(transfer: transfer); Button("Cancel", role: .destructive) { Task { try? await state.transferManager.cancel(id: transfer.id) } } } }; Section("Completed") { ForEach(state.transferManager.completed) { TransferRow(transfer: $0) } } }.navigationTitle("Transfers") } }
struct IOSNotesView: View { @EnvironmentObject private var state: SyncSpaceAppState; @State private var composing = false; var body: some View { List(state.recentNotes) { note in NavigationLink { ScrollView { Text(note.content).frame(maxWidth: .infinity, alignment: .leading).padding() }.navigationTitle(note.title) } label: { VStack(alignment: .leading) { HStack { Text(note.title).font(.headline); if !note.isRead { Circle().fill(.tint).frame(width: 8) } }; Text(note.content).lineLimit(2).foregroundStyle(.secondary) } } }.overlay { if state.recentNotes.isEmpty { ContentUnavailableView("No notes", systemImage: "note.text", description: Text("Received and sent notes will appear here.")) } }.navigationTitle("Notes").toolbar { Button("New note", systemImage: "square.and.pencil") { composing = true }.disabled(true) } } }
struct IOSSettingsView: View { @EnvironmentObject private var state: SyncSpaceAppState; var body: some View { Form { Section("Server") { TextField("Hostname or IP", text: $state.settings.serverHost).textInputAutocapitalization(.never).autocorrectionDisabled(); TextField("Port", value: $state.settings.serverPort, format: .number).keyboardType(.numberPad); Toggle("Use HTTPS", isOn: $state.settings.useHTTPS); Toggle("Auto-connect", isOn: $state.settings.autoConnect); Toggle("WebSocket updates", isOn: $state.settings.webSocketUpdates) }; Section("Preferences") { Toggle("Notifications", isOn: $state.settings.showNotifications); Toggle("Save transfer history", isOn: $state.settings.saveTransferHistory); TextField("Device name override", text: $state.settings.deviceNameOverride); Toggle("Debug logging", isOn: $state.settings.debugLogging) }; Section("Privacy") { Text("SyncSpace is LAN-first. Clipboard and file sharing require explicit action. Sensitive content is not logged by default.") }; Section("About") { LabeledContent("App version", value: "0.1.0 foundation") } }.navigationTitle("Settings").toolbar { Button("Save") { state.saveSettings() } } } }
